// Part: room: dining room (interior furnisher, East front formal dining). Inner air box [52,4,43,68,9,49], floor y4.
// Long table on the centre line z44 (fence legs, top slab, x56..66) with five chairs each side; a barrel sideboard on the
// east wall; three hanging lanterns on iron_chain over the table and the south lane. Lanes: z46..47 from the hall door
// (x51) and z48..49 both stay clear; the chimney at x61..62 z46..47 is left to the roofs part.
import { B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const WOOD = "dark_oak";

export function build(g) {
  // table: fence legs at y4, top slab (type top) at y5 resting on the fence tops
  for (let x = 56; x <= 66; x++) {
    g.set(x, 4, 44, ...B.fence(WOOD));
    g.set(x, 5, 44, ...B.slab(WOOD, "top"));
  }
  // chairs: the north row faces south (back to the north wall), the south row faces north
  for (const x of [57, 59, 61, 63, 65]) {
    g.set(x, 4, 43, ...B.stairs(WOOD, "north", "bottom"));
    g.set(x, 4, 45, ...B.stairs(WOOD, "south", "bottom"));
  }
  // sideboard on the east wall: three barrels, a lit candle on the middle one
  for (const z of [43, 44, 45]) g.set(68, 4, z, "barrel", { facing: "up" });
  g.set(68, 5, 44, "candle", { candles: "2", lit: "true" });
  // hanging lanterns: over the table, and over the south lane
  for (const [x, z] of [[61, 44], [53, 44], [54, 48], [59, 48], [67, 48]]) {
    g.set(x, 9, z, ...B.chain("y"));
    g.set(x, 8, z, ...B.lantern(true));
  }
}
